 "content": "def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) < 2:
        return out

    # The 5 embedded in a colored pattern is the source; copy that pattern
    # relative to the other 5, which acts as the destination marker.
    def nearby_count(anchor):
        ar, ac = anchor
        return sum(
            1 for r, row in enumerate(grid) for c, v in enumerate(row)
            if v != 0 and v != 5 and (r, c) != anchor
            and max(abs(r - ar), abs(c - ac)) <= 4
        )

    source = max(anchors, key=nearby_count)
    dest = next(a for a in anchors if a != source)
    sr, sc = source
    dr, dc = dest
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0 and value != 5:
                rr, cc = dr + r - sr, dc + c - sc
                if 0 <= rr < len(out) and 0 <= cc < len(out[rr]):
                    out[rr][cc] = value
    out[dr][dc] = 0
    return out
